def main():
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()))
    OUT.mkdir(parents=True, exist_ok=True)
    total = 0
    counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    written = 0
    for cid in IDS:
        d = P[cid]
        obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        path = OUT / f"{cid}.json"
        path.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
        written += 1
    # per-file self-verification: parse, fields, id match
    for cid in IDS:
        path = OUT / f"{cid}.json"
        obj = json.loads(path.read_text(encoding="utf-8"))
        assert obj["case_id"] == cid and path.stem == cid
        assert set(obj.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
        assert isinstance(obj["confidence"], (int, float)) and 0 <= obj["confidence"] <= 1
        tg = obj["trigger"]
        assert set(tg.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        for k in counts:
            if tg[k]:
                counts[k] += 1
        total += path.stat().st_size
    assert written == 20
    print(json.dumps({"cases": len(IDS), "written": written, "trigger_counts": counts, "total_bytes": total}, ensure_ascii=False))

if __name__ == "__main__":
    main()
